const event = $input.first().json;
if (event.event !== "task" || event.capability !== "demo.order-status") {
  throw new Error("Unexpected AGX event");
}
const base = { source: "agx-get-started-demo", demo: true };
const orderId = event.payload?.orderId;
if (typeof orderId !== "string" || orderId.length > 32 || !/^DEMO-\d{4}$/.test(orderId)) {
  return [{ json: { ...base, found: false, error: "invalid-order-id" } }];
}
const orders = new Map([
  ["DEMO-1001", { status: "ready-for-pickup", nextStep: "Collect at the fictional demo warehouse." }],
  ["DEMO-1002", { status: "in-transit", nextStep: "Check the fictional tracking record tomorrow." }],
  ["DEMO-1003", { status: "awaiting-review", nextStep: "Ask the fictional demo operator to review the record." }],
]);
const record = orders.get(orderId);
if (!record) {
  return [{ json: { ...base, found: false, error: "order-not-found" } }];
}
return [{ json: { ...base, orderId, found: true, ...record } }];
